import{_ as t,o,c as a,ak as i,am as n,an as r,at as s,au as c}from"./chunks/framework.CYL5YPWS.js";const w=JSON.parse('{"title":"Save & quickly warp in Grindr","description":"","frontmatter":{},"headers":[],"relativePath":"guides/features/command-center/quick-warp/index.md","filePath":"guides/features/command-center/quick-warp/index.md"}'),h={name:"guides/features/command-center/quick-warp/index.md"};function p(d,e,u,l,m,g){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="save-quickly-warp-in-grindr" tabindex="-1">Save &amp; quickly warp in Grindr <a class="header-anchor" href="#save-quickly-warp-in-grindr" aria-label="Permalink to “Save &amp; quickly warp in Grindr”">​</a></h1><p>To save and then quickly teleport yourself in Grindr, use the <a href="/guides/features/command-center/">Command Center</a>.</p><p>First, copy the geohash location. Geohash is a string of characters like <code>u3buwp3k26wx</code> that works like coordinates and encodes precise location. In this guide we&#39;ll be copying the geohash from the location you have set in the app, but you can also use <a href="https://geohash.softeng.co/" target="_blank" rel="noreferrer">Geohash Explorer</a> to encode coordinates to geohash.</p><p>Locate the <img src="'+n+'" width="41.5" height="36" class="inline" alt="Feed input icon, “&gt;_”"> button, at the end of filters top bar on the main &quot;Browse&quot; page. Tap it, which opens the Command Center. You can also use <code>⌘ + K</code> on macOS and <code>Ctrl + K</code> on Windows and Linux to open it.</p><img src="'+r+'" width="408" height="273" style="margin-inline:auto;" alt="Popup with “Quick actions...” input"><p>Now in the Command Center, put <code>@</code>, which should prompt you to copy the currently selected location.</p><img src="'+s+'" width="446" height="165" style="margin-inline:auto;" alt="“Set location by geohash...” sub-menu of the popup with “Copy to clipboard” action"><p>Now you have the location copied, write it down somewhere, like in a note-taking app. When you want to quickly set the location to this point, open the Command Center again, put <code>@</code> and then the geohash, e.g. <code>@u3buwp3k26wx</code>.</p><img src="'+c+'" width="446" height="309" style="margin-inline:auto;" alt="“Set location by geohash...” sub-menu of the popup">',9)])])}const f=t(h,[["render",p]]);export{w as __pageData,f as default};
